    { cat: 'usecases', icon: 'campaign',        label: 'Ad Campaign Brief',      text: 'Create an ad campaign brief for [[campaign_name]].\\n\\nProduct: [[product]]\\nAudience: [[audience]]\\nBudget: [[budget]]\\nDuration: [[duration]]\\nGoal: [[goal — awareness / conversions / retention]]\\n\\nCampaign brief:\\n- Campaign concept (2 sentences)\\n- Core message\\n- Channels (ranked by priority)\\n- Creative direction\\n- Key metrics (what we will measure)\\n- What success looks like\\n- Constraints (what we must not do)' },
    { cat: 'usecases', icon: 'calendar_month',  label: 'Content Calendar',       text: 'Plan a [[duration]]-week content calendar for [[brand_or_project]].\\n\\nChannels: [[channels]]\\nContent themes: [[themes]]\\nPosting frequency: [[frequency]]\\n\\nCalendar format:\\nWeek 1:\\n  Mon: [content type] — [topic] — [channel]\\n  Wed: [content type] — [topic] — [channel]\\n  Fri: [content type] — [topic] — [channel]\\n\\n[Repeat for each week]\\n\\nContent mix target: [[N]]% educational, [[N]]% promotional, [[N]]% engagement' },
    { cat: 'usecases', icon: 'video_library',   label: 'YouTube Script',         text: 'Write a YouTube script for a [[length]]-minute video on: [[topic]]\\n\\nChannel audience: [[audience]]\\nVideo goal: [[goal]]\\nCall to action: [[cta]]\\n\\nScript structure:\\n[HOOK 0:00-0:30] — Pattern interrupt + promise\\n[INTRO 0:30-1:00] — What you will cover, why it matters\\n[MAIN CONTENT 1:00-[[length minus 1]]min] — [3-5 sections with timestamps]\\n[CTA [[final minute]]] — Subscribe / like / comment prompt + next video tease\\n\\nInclude: B-roll suggestions in [brackets]' },
