    { cat: 'usecases', icon: 'assignment',      label: 'Product Requirements',   text: 'Write a product requirements document (PRD) for: [[feature_name]]\\n\\nProduct: [[product]]\\nOwner: [[owner]]\\nTarget launch: [[launch_date]]\\n\\nSections:\\n1. Problem statement\\n2. Goals and success metrics\\n3. User stories (minimum 5)\\n4. Functional requirements\\n5. Non-functional requirements\\n6. Out of scope\\n7. Dependencies\\n8. Open questions\\n9. Timeline' },
