# ── 4. Apply insertions ────────────────────────────────────────────────────

# Insert new blocks just before `\n  ];\n\n  var FRAMEWORKS`
BLOCKS_ANCHOR = '\n  ];\n\n  var FRAMEWORKS = ['
assert BLOCKS_ANCHOR in code, "BLOCKS_ANCHOR not found"
code = code.replace(BLOCKS_ANCHOR, NEW_BLOCKS + BLOCKS_ANCHOR, 1)

# Insert new frameworks just before `\n  ];\n\n  var _canvasBlocks`
FRAMEWORKS_ANCHOR = '\n  ];\n\n  var _canvasBlocks'
assert FRAMEWORKS_ANCHOR in code, "FRAMEWORKS_ANCHOR not found"
code = code.replace(FRAMEWORKS_ANCHOR, NEW_FRAMEWORKS + FRAMEWORKS_ANCHOR, 1)

open('static/app.js', 'w', encoding='utf-8').write(code)

# Count results
import re
pcw_idx = code.index('(function initComponentsWorkspace()')
# Find IIFE end
depth=0; pos=pcw_idx; found=-1
while pos < len(code) and found == -1:
    if code[pos] == '(': depth += 1
    elif code[pos] == ')':
        depth -= 1
        if depth == 0 and pos > pcw_idx + 10: found = pos
    pos += 1
section = code[pcw_idx:found+2]

block_count = len(re.findall(r"cat: '(\w+)'", section))
fw_count = len(re.findall(r"badge: '", section))
cat_ids = re.findall(r"id: '(\w+)'", section[:section.index('var BLOCKS')])
print('Blocks:', block_count)
print('Frameworks:', fw_count)
print('Categories:', cat_ids)
print('Done.')
